<template><div class="app-container"><el-alert type="info" :closable="false" title="仅审核确认的工作量计入进度；完成与归档后只读。企业任务仍仅本企业内部使用。"/>
<el-form inline><el-select v-if="!personalMode" v-model="companyId" @change="load"><el-option v-for="c in companies" :key="c.id" :label="c.company_name" :value="c.id"/></el-select><el-button @click="load">刷新</el-button><el-button v-if="!personalMode" v-hasPermi="['biz:execution:manage']" type="primary" @click="openLink">从已通过报名创建/关联项目</el-button></el-form>
<el-table v-if="!personalMode" :data="rows" v-loading="loading"><el-table-column prop="project_name" label="项目名称"/><el-table-column prop="project_code" label="编号"/><el-table-column prop="unit" label="单位"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="viewProject(row.id)">进度、分配与核验</el-button></template></el-table-column></el-table>
<el-table v-else :data="rows" v-loading="loading"><el-table-column prop="title" label="任务"/><el-table-column prop="assigned_quantity" label="分配量"/><el-table-column prop="unit" label="单位"/><el-table-column prop="due_date" label="截止日"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="操作" width="330"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link type="primary" @click="claim(row)">领取</el-button><el-button link @click="viewMine(row.id)">详情与工作量</el-button><el-button v-if="row.status==='EXECUTING'" link @click="finish(row)">完成任务</el-button></template></el-table-column></el-table>
<el-dialog v-model="linkVisible" title="审核通过任务创建或关联项目" width="570px"><el-form label-width="110px"><el-form-item label="已通过报名"><el-select v-model="linkForm.signupId"><el-option v-for="s in approved" :key="s.id" :label="`${s.title}（${s.promised_quantity}${s.unit}）`" :value="s.id"/></el-select></el-form-item><el-form-item label="关联现有项目"><el-select v-model="linkForm.projectId" clearable placeholder="留空则创建新项目"><el-option v-for="p in rows.filter(p=>p.status==='ACTIVE')" :key="p.id" :label="p.project_name" :value="p.id"/></el-select></el-form-item><el-form-item v-if="!linkForm.projectId" label="新项目名称"><el-input v-model="linkForm.projectName" maxlength="100"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="saveLink">确定</el-button></template></el-dialog>
<el-dialog v-model="projectVisible" title="项目执行、成员工作量与归档" width="92%"><p>目标 {{project.totalQuantity}} {{project.unit}}，已确认 {{project.confirmedQuantity}}，剩余 {{project.remainingQuantity}}，状态 {{states[project.status]}}</p><el-progress :percentage="Number(project.percent||0)"/>
<div class="mb8"><el-button v-if="project.status==='ACTIVE'" v-hasPermi="['biz:execution:manage']" @click="openAssign">分配任务</el-button><el-button v-if="project.status==='ACTIVE'" v-hasPermi="['biz:execution:manage']" @click="completeProject(false)">项目完成确认</el-button><el-button v-if="project.status==='COMPLETED'" v-hasPermi="['biz:execution:manage']" @click="completeProject(true)">归档项目</el-button><el-button @click="viewProject(project.id)">刷新项目</el-button></div>
<el-tabs><el-tab-pane label="任务分配与成员进度"><el-table :data="project.assignments||[]"><el-table-column prop="id" label="分配编号"/><el-table-column prop="real_name" label="员工"/><el-table-column prop="task_id" label="任务编号"/><el-table-column prop="assigned_quantity" label="分配量"/><el-table-column prop="confirmed_quantity" label="已确认量"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='PENDING'&&project.status==='ACTIVE'" v-hasPermi="['biz:execution:manage']" link @click="cancel(row)">取消待领取分配</el-button></template></el-table-column></el-table><h4>成员汇总</h4><el-table :data="project.members||[]"><el-table-column prop="userId" label="账号编号"/><el-table-column prop="confirmedQuantity" label="已确认总工作量"/></el-table></el-tab-pane>
<el-tab-pane label="工作量审核"><el-table :data="project.workRecords||[]"><el-table-column prop="user_id" label="员工账号"/><el-table-column prop="work_date" label="工作日期"/><el-table-column prop="quantity" label="工作量"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="操作" width="280"><template #default="{row}"><template v-if="project.status==='ACTIVE'"><el-button v-if="row.status==='SUBMITTED'" v-hasPermi="['biz:execution:manage']" link @click="review(row,true)">确认</el-button><el-button v-if="row.status==='SUBMITTED'" v-hasPermi="['biz:execution:manage']" link @click="review(row,false)">退回</el-button><el-button v-if="row.status==='CONFIRMED'" v-hasPermi="['biz:execution:manage']" link @click="reopen(row)">退回更正</el-button></template></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="变更轨迹"><el-table :data="project.events||[]"><el-table-column prop="action" label="操作"/><el-table-column prop="opinion" label="说明"/><el-table-column prop="before_value" label="变更前" show-overflow-tooltip/><el-table-column prop="after_value" label="变更后" show-overflow-tooltip/><el-table-column prop="actor_id" label="操作人"/><el-table-column prop="create_time" label="时间"/></el-table></el-tab-pane></el-tabs></el-dialog>
<el-dialog v-model="assignVisible" title="向本企业员工分配任务"><el-form label-width="110px"><el-form-item label="项目内任务"><el-select v-model="assign.signupId"><el-option v-for="s in project.links||[]" :key="s.signup_id" :label="`${s.title}（${s.target_quantity}${s.unit}）`" :value="s.signup_id"/></el-select></el-form-item><el-form-item label="员工"><el-select v-model="assign.userId" filterable><el-option v-for="s in staff" :key="s.user_id" :label="`${s.real_name}（${s.user_id}）`" :value="s.user_id"/></el-select></el-form-item><el-form-item label="分配工作量"><el-input-number v-model="assign.quantity" :min="0.01" :precision="2"/></el-form-item><el-form-item label="截止日期"><el-date-picker v-model="assign.dueDate" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="saveAssign">分配</el-button></template></el-dialog>
<el-dialog v-model="mineVisible" title="我的每日工作量与轨迹" width="88%"><el-button v-if="mine.status==='EXECUTING'" @click="editWork()">新增每日工作量</el-button><el-table :data="mine.records||[]"><el-table-column prop="work_date" label="工作日期"/><el-table-column prop="quantity" label="工作量"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="操作" width="270"><template #default="{row}"><template v-if="mine.status==='EXECUTING'"><el-button v-if="['DRAFT','RETURNED','VOID'].includes(row.status)" link @click="editWork(row)">修改</el-button><el-button v-if="['DRAFT','RETURNED'].includes(row.status)" link type="primary" @click="submitWork(row)">提交</el-button><el-button v-if="['DRAFT','RETURNED'].includes(row.status)" link type="danger" @click="voidWork(row)">作废</el-button></template></template></el-table-column></el-table><el-table :data="mine.events||[]"><el-table-column prop="action" label="操作"/><el-table-column prop="opinion" label="审核意见/说明"/><el-table-column prop="create_time" label="时间"/></el-table></el-dialog>
<el-dialog v-model="workVisible" title="每日工作量"><el-form label-width="110px"><el-form-item label="工作日期"><el-date-picker v-model="work.workDate" value-format="YYYY-MM-DD" :disabled="!!work.id"/></el-form-item><el-form-item label="工作量"><el-input-number v-model="work.quantity" :min="0.01" :precision="2"/></el-form-item><el-form-item label="说明"><el-input v-model="work.remark" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button :loading="saving" type="primary" @click="saveWork">保存草稿</el-button></template></el-dialog>
</div></template>
<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const route=useRoute(),personalMode=computed(()=>route.path.endsWith('execution-mine')),rows=ref([]),companies=ref([]),companyId=ref(),loading=ref(false),saving=ref(false),project=ref({}),approved=ref([]),staff=ref([]),mine=ref({}),work=ref({}),assign=ref({}),linkForm=ref({}),linkVisible=ref(false),projectVisible=ref(false),assignVisible=ref(false),mineVisible=ref(false),workVisible=ref(false)
const states={ACTIVE:'执行中',PENDING:'待领取',EXECUTING:'执行中',COMPLETED:'已完成',ARCHIVED:'已归档',CANCELLED:'已取消',DRAFT:'草稿',SUBMITTED:'待核验',CONFIRMED:'已确认',RETURNED:'退回更正',VOID:'已作废'}
async function load(){loading.value=true;try{if(personalMode.value)rows.value=(await request({url:'/execution/mine'})).data;else{companies.value=(await request({url:'/execution/companies'})).data;if(!companyId.value)companyId.value=companies.value[0]?.id;if(companyId.value)rows.value=(await request({url:'/execution/projects',params:{companyId:companyId.value}})).data}}finally{loading.value=false}}
async function openLink(){approved.value=(await request({url:'/execution/approved'})).data;linkForm.value={};linkVisible.value=true}
async function saveLink(){saving.value=true;try{await request({url:'/execution/projects',method:'post',data:linkForm.value});linkVisible.value=false;await load()}finally{saving.value=false}}
async function viewProject(id){project.value=(await request({url:'/execution/projects/'+id,params:{companyId:companyId.value}})).data;projectVisible.value=true}
async function openAssign(){staff.value=(await request({url:'/execution/staff'})).data;assign.value={};assignVisible.value=true}
async function saveAssign(){saving.value=true;try{await request({url:`/execution/projects/${project.value.id}/assignments`,method:'post',data:assign.value});assignVisible.value=false;await viewProject(project.value.id)}finally{saving.value=false}}
async function opinion(title){return (await ElMessageBox.prompt('请输入操作或审核意见',title,{inputPattern:/\S+/,inputErrorMessage:'意见必填'})).value}
async function cancel(row){await request({url:`/execution/assignments/${row.id}/cancel`,method:'post',data:{version:row.version,opinion:await opinion('取消分配')}});await viewProject(project.value.id)}
async function completeProject(archive){await request({url:`/execution/projects/${project.value.id}/${archive?'archive':'complete'}`,method:'post',data:{version:project.value.version,opinion:await opinion(archive?'项目归档':'完成确认')}});await viewProject(project.value.id);await load()}
async function review(row,approve){await request({url:`/execution/records/${row.id}/review`,method:'post',data:{version:row.version,approve,opinion:await opinion(approve?'工作量确认':'工作量退回')}});await viewProject(project.value.id)}
async function reopen(row){await request({url:`/execution/records/${row.id}/reopen`,method:'post',data:{version:row.version,opinion:await opinion('退回更正')}});await viewProject(project.value.id)}
async function claim(row){await request({url:`/execution/assignments/${row.id}/claim`,method:'post',data:{version:row.version}});await load()}
async function finish(row){await request({url:`/execution/assignments/${row.id}/finish`,method:'post',data:{version:row.version}});ElMessage.success('分配任务已完成');await load()}
async function viewMine(id){mine.value=(await request({url:'/execution/mine/'+id})).data;mineVisible.value=true}
function editWork(row){work.value=row?{id:row.id,workDate:String(row.work_date).slice(0,10),quantity:Number(row.quantity),remark:row.remark,version:row.version}:{workDate:new Date().toLocaleDateString('sv-SE'),quantity:1,remark:''};workVisible.value=true}
async function saveWork(){saving.value=true;try{await request({url:`/execution/assignments/${mine.value.id}/records`+(work.value.id?'/'+work.value.id:''),method:work.value.id?'put':'post',data:work.value});workVisible.value=false;await viewMine(mine.value.id)}finally{saving.value=false}}
async function submitWork(row){await request({url:`/execution/records/${row.id}/submit`,method:'post',data:{version:row.version}});await viewMine(mine.value.id)}
async function voidWork(row){await request({url:`/execution/records/${row.id}/void`,method:'post',data:{version:row.version,opinion:await opinion('作废草稿或退回记录')}});await viewMine(mine.value.id)}
watch(personalMode,()=>{rows.value=[];companyId.value=undefined;projectVisible.value=false;mineVisible.value=false;load()});onMounted(load)
</script>
